For all $q\in (2,\infty)$, $\alpha \in (0,\frac{q-2}{2 q})$ 
it holds that (the pathwise continuous version of) the local time $L_\cdot(Y)$ is locally $\alpha$-H\"older continuous.
In particular for all $\delta \in (-\infty,\frac12)$, $T\in [0,\infty)$ it holds that
\begin{equation} 
	\sup_{t\in [0,T]} n^{\delta} \left(L_{ t +\frac1n }(Y) - L_t(Y)\right) \xrightarrow[n\to\infty]{\mathrm{a.s.}} 0.\end{equation}

Let $(g_n)_{n\in \mathbb{N}}$ be a sequence of real functions satisfying that $\langle \lambda_\sigma , g_n \rangle=0$ and for all $x\in \mathbb{R}$
\begin{equation} 
	\lim_{n\to\infty} \frac{g_n(x\sqrt{n})^2}{n}+ \frac{\|g_n^2\|_{1}}{\sqrt{n}} + \frac{\| g_n \|_{1,1}|g_n(x \sqrt{n})|\log(n)}{n} + \frac{\| g_n \|_{1,1} \|g_n\|_{1} \log(n)}{\sqrt{n}}
=0.
\end{equation}
Then
$\lim_{n\to\infty} \mathbb{E}\!\left[\left(\frac{1}{\sqrt{n}}  \sum_{k=0}^{\lfloor n t \rfloor-1} g_n(\sqrt{n} Y_{\frac{k}n}) \right)^2\right]=0$
for all $t\in [0,1]$.

Let $g_n \colon \mathbb{R} \to \mathbb{R}$, $n\in \mathbb{N}$, be a sequence of functions satisfying (B.12)
and there exists $\lambda\in \mathbb{R}$ such that $\lim_{n\to\infty} \langle \lambda_\sigma , g_n \rangle=\lambda$.
Then for all $t\in [0,1]$ it holds that 
\begin{equation}
	\frac1{\sqrt{n}}  \sum_{k=0}^{\lfloor n t \rfloor-1} g_n(\sqrt{n} Y_{\frac{k}n})  \xrightarrow[n\to\infty]{\mathbb{P}} \lambda L_t(Y).
\end{equation}
If in addition $\sup_{n\in \mathbb{N}} \|g_n\|_{1} <\infty$ 
then 
\begin{equation}
	\sup_{s\in [0,1]} \Big| n^{-1/2}  \sum_{k=0}^{\lfloor n s \rfloor-1} g_n(\sqrt{n} Y_{\frac{k}n}) - \lambda L_s(Y)\Big|\xrightarrow[n\to\infty]{\mathbb{P}} 0.
\end{equation}

Let $x\in \mathbb{R}$,
let $W$ be a standard BM and $Y$ be a standard OBM defined on the same probability space,
let $f\colon \mathbb{R} \to \mathbb{R}$ be a function satisfying that there exist $K,\alpha\in [0,\infty)$ such that $|f(y)|\leq K e^{\alpha |y|}$ for all $y\in \mathbb{R}$. 
Then for all $p\in \mathbb{N}$ it hold that
\begin{equation}
\begin{split} 
	& \mathbb{L}^{(p)}(f,x)
	 = \int_0^1 \frac{|x|}{\sigma(x)} \frac{(1-t)^\frac{p}{2}}{\sqrt{2\pi} t^\frac32} e^{-\frac{x^2}{2 (\sigma(x))^2 t}} 
	\mathbb{E}\!\left[ \left( L_1(Y)\right)^p f(Y_1 \sqrt{1-t})\right]\! \,\mathrm{d} t
	\\
	& 
	= \left(\frac{2 \sigma_-\sigma_+}{\sigma_-+\sigma_+}\right)^{\! (p+1)} \frac{|x|}{\sigma(x)}
	\int_0^1  \frac{(1-t)^\frac{p}{2}}{\sqrt{2\pi} t^\frac32} e^{-\frac{x^2}{2 (\sigma(x))^2 t}} 
	\mathbb{E}\!\left[ \left( L_1(W)\right)^p (\sigma(W_1))^{-1} f(\sigma( W_1) W_1 \sqrt{1-t})  \right] \! \,\mathrm{d} t,
\end{split}
\end{equation}
if $x\neq 0$, and 
$ 
	\mathbb{L}^{(p)}(f,0)
	= \left(\frac{2 \sigma_-\sigma_+}{\sigma_-+\sigma_+}\right)^{\! (p+1)} 
	\mathbb{E}\!\left[ \left( L_1(W)\right)^p (\sigma(W_1))^{-1} f(\sigma( W_1) W_1) \right] \!.
$\\
(If $\sigma_\pm=\infty$ then replace $f$ in the right hand side of last two equalities with $f \mathbf{1}_{\mathbb{R}_\mp}$.)
